-- gen597: 12 zone cambiate, 25 tessere
-- 46881a1596b5bcb814f3431a5a1c7f13 (792436) → 1d6e3ca91559e6bf617c89095ab00a52 (801714)

  on conflict (key) do update set value=excluded.value;


-- il cancello, PRIMA di scrivere
select md5(string_agg(value, '' order by key)) as md5_ricomposto,
       length(string_agg(value, '' order by key)) as len_ricomposto,
       md5(string_agg(value, '' order by key)) = '1d6e3ca91559e6bf617c89095ab00a52' as combacia
from kv_store where key like 'tmp:gen597:p%';

update kv_store set value = (select string_agg(value, '' order by key) from kv_store where key like 'tmp:gen597:p%')
where key='app:jsx:src'
  and md5(value) = '46881a1596b5bcb814f3431a5a1c7f13'
  and (select md5(string_agg(value, '' order by key)) from kv_store where key like 'tmp:gen597:p%') = '1d6e3ca91559e6bf617c89095ab00a52';

update kv_store set value = '{"len":801714,"ver":"gen-5.97"}'
where key='app:jsx:meta'
  and (select md5(value) from kv_store where key='app:jsx:src') = '1d6e3ca91559e6bf617c89095ab00a52';

delete from kv_store where key like 'tmp:gen597:p%';
